package com.runloyal.booking.web;
import com.runloyal.booking.context.TenantContext; import com.runloyal.booking.domain.*; import com.runloyal.booking.service.PlatformService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api") public class ApiController { final PlatformService p; final TenantContext ctx; public ApiController(PlatformService p,TenantContext c){this.p=p;ctx=c;} @GetMapping("/me") public AppUser me(){return ctx.user();}
 @GetMapping("/services") public List<ServiceOffering> services(){return p.services();} @PostMapping("/services") @ResponseStatus(HttpStatus.CREATED) public ServiceOffering createService(@Valid @RequestBody Dto.ServiceCommand c){return p.saveService(c,null);} @PutMapping("/services/{id}") public ServiceOffering updateService(@PathVariable UUID id,@Valid @RequestBody Dto.ServiceCommand c){return p.saveService(c,id);}@DeleteMapping("/services/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void deleteService(@PathVariable UUID id){p.deleteService(id);}
 @GetMapping("/staff") public List<Staff> staff(){return p.staffs();}@PostMapping("/staff")@ResponseStatus(HttpStatus.CREATED)public Staff createStaff(@Valid @RequestBody Dto.StaffCommand c){return p.saveStaff(c,null);}@PutMapping("/staff/{id}")public Staff updateStaff(@PathVariable UUID id,@Valid @RequestBody Dto.StaffCommand c){return p.saveStaff(c,id);}
 @PostMapping("/services/{service}/staff/{staff}")@ResponseStatus(HttpStatus.NO_CONTENT)public void assign(@PathVariable UUID service,@PathVariable UUID staff){p.assign(service,staff,true);}@DeleteMapping("/services/{service}/staff/{staff}")@ResponseStatus(HttpStatus.NO_CONTENT)public void unassign(@PathVariable UUID service,@PathVariable UUID staff){p.assign(service,staff,false);}
 @GetMapping("/staff/{staff}/availability")public List<StaffAvailability> availability(@PathVariable UUID staff){return p.availability(staff);}@PostMapping("/staff/{staff}/availability")public StaffAvailability addAvailability(@PathVariable UUID staff,@Valid @RequestBody Dto.AvailabilityCommand c){return p.saveAvailability(staff,c,null);}@PutMapping("/staff/{staff}/availability/{id}")public StaffAvailability putAvailability(@PathVariable UUID staff,@PathVariable UUID id,@Valid @RequestBody Dto.AvailabilityCommand c){return p.saveAvailability(staff,c,id);}@DeleteMapping("/staff/{staff}/availability/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delAvailability(@PathVariable UUID staff,@PathVariable UUID id){p.deleteAvailability(id);}
 @GetMapping("/services/{service}/available-staff")public List<Staff> available(@PathVariable UUID service,@RequestParam Instant startAt){return p.available(service,startAt);}@GetMapping("/bookings")public List<Booking> bookings(@RequestParam Instant from,@RequestParam Instant to){return p.calendar(from,to);}@PostMapping("/bookings")@ResponseStatus(HttpStatus.CREATED)public Booking book(@Valid @RequestBody Dto.BookingCommand c){return p.book(c);}@GetMapping("/bookings/{id}")public Booking booking(@PathVariable UUID id){return p.booking(id);}@PostMapping("/bookings/{id}/cancel")public Booking cancel(@PathVariable UUID id){return p.cancel(id);}}
